function openPopup(){document.getElementById("popup").style.display="block",document.getElementById("overlay").style.display="block"}function closePopup(){document.getElementById("popup").style.display="none",document.getElementById("overlay").style.display="none"}document.addEventListener("DOMContentLoaded",function(){var e=document.querySelectorAll(".theme-toggle");if(e.length){var t=function(){var t="dark"===document.documentElement.getAttribute("data-theme");e.forEach(function(e){e.setAttribute("aria-pressed",String(t))})};e.forEach(function(e){e.addEventListener("click",function(){var e="dark"===document.documentElement.getAttribute("data-theme")?"light":"dark";document.documentElement.setAttribute("data-theme",e),localStorage.setItem("theme",e),t()})}),t()}});